#!/usr/bin/env node
/**
 * Patches native dependency metadata after install (ios/ is generated by prebuild, so fixes
 * must live here instead of in native files).
 *
 * react-native-date-picker@5 registers its iOS view manager (RNDatePickerManager) as a
 * TurboModule provider in `codegenConfig.ios.modulesProvider`. On RN 0.83 the generated
 * RCTModuleProviders rejects it at startup with "Module provider RNDatePickerManager does not
 * conform to RCTModuleProvider". The app only uses the inline picker (a Fabric component), so
 * dropping the module provider entry is safe.
 */
const fs = require('fs');
const path = require('path');

const packageJsonPath = path.join(
  __dirname,
  '..',
  'node_modules',
  'react-native-date-picker',
  'package.json'
);

function patchDatePicker() {
  if (!fs.existsSync(packageJsonPath)) {
    return;
  }

  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
  const iosConfig = packageJson.codegenConfig && packageJson.codegenConfig.ios;

  if (!iosConfig || !iosConfig.modulesProvider) {
    return;
  }

  delete iosConfig.modulesProvider;
  fs.writeFileSync(packageJsonPath, `${JSON.stringify(packageJson, null, 2)}\n`);
  console.log('[patch-native-deps] Removed iOS modulesProvider from react-native-date-picker');
}

patchDatePicker();
